/**
 * A gated context push must never block write/edit. The content is already
 * generated by the time `tool_call` fires, so blocking discards the whole write
 * to force a doc read (observed: a 1000-line TS write thrown away because
 * ctx-coding-style escalated). The reminder still lands on tool_result, and
 * cheap actions keep the escalation block.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

const say = (msg: string): void => console.log(msg);

const root = fs.mkdtempSync(path.join(os.tmpdir(), "ttsr-escalation-test-"));
const fakeHome = path.join(root, "home");
const fakeCwd = path.join(root, "repo");
const rulesDir = path.join(fakeHome, ".pi", "agent", "rules");
const ctxDir = path.join(fakeHome, ".pi", "contexts");
fs.mkdirSync(rulesDir, { recursive: true });
fs.mkdirSync(ctxDir, { recursive: true });
fs.mkdirSync(path.join(fakeCwd, "src"), { recursive: true });

for (const doc of ["style.md", "deploy.md"]) {
	fs.writeFileSync(path.join(ctxDir, doc), `# ${doc}\n\nfixture\n`);
}

fs.writeFileSync(
	path.join(ctxDir, "registry.yaml"),
	`version: 1
contexts:
  - id: style-doc
    file: style.md
    when: before authoring TypeScript
    tier: gated
    gate:
      mode: none
    triggers:
      - tool: '^(write|edit)$'
        globs: ['**/*.ts']
  - id: deploy-doc
    file: deploy.md
    when: before running a deploy command
    tier: gated
    gate:
      mode: none
    triggers:
      - tool: '^bash$'
        match: 'deploy'
`,
);

process.env.HOME = fakeHome;
delete process.env.TTSR_CONTEXT_REGISTRY;
delete process.env.PI_SUBAGENT_CHILD;

type Handler = (event: unknown, ctx: unknown) => unknown;
interface FakePi {
	on(ev: string, h: Handler): void;
	registerCommand(cmd: unknown): void;
	registerTool(tool: unknown): void;
	appendEntry(type: string, data: unknown): void;
	sendUserMessage(msg: string, opts?: unknown): void;
}
type EngineFactory = (api: FakePi) => Promise<void>;

function makeFakePi() {
	const handlers: Record<string, Handler[]> = {};
	const pi: FakePi = {
		on: (ev, h) => {
			(handlers[ev] ??= []).push(h);
		},
		registerCommand: () => {},
		registerTool: () => {},
		appendEntry: () => {},
		sendUserMessage: () => {},
	};
	return { pi, handlers };
}

function makeCtx() {
	return {
		hasUI: false,
		cwd: fakeCwd,
		isProjectTrusted: () => false,
		isIdle: () => true,
		abort: () => {},
		ui: { notify: () => {} },
		sessionManager: { getSessionId: () => "test-session", getBranch: () => [], getEntries: () => [] },
	};
}

let fail = 0;
const check = (cond: boolean, msg: string): void => {
	if (!cond) {
		say(`FAIL: ${msg}`);
		fail++;
	}
};

// The real factory takes the full ExtensionAPI; the fake implements only the
// subset the engine uses, so the assignment needs one structural escape here.
const engineFactory = (await import("./index.ts")).default as unknown as EngineFactory;

const { pi, handlers } = makeFakePi();
await engineFactory(pi);
const ctx = makeCtx();
for (const h of handlers["session_start"] ?? []) await h({}, ctx);
for (const h of handlers["turn_start"] ?? []) await h(undefined, ctx);

const toolCall = handlers["tool_call"]?.[0];
const toolResult = handlers["tool_result"]?.[0];
if (!toolCall) throw new Error("no tool_call handler registered");

const turnStart = async (): Promise<void> => {
	for (const h of handlers["turn_start"] ?? []) await h(undefined, ctx);
};
const call = (toolName: string, input: Record<string, string>, id: string) =>
	toolCall({ toolName, input, toolCallId: id }, ctx) as Promise<{ block?: boolean } | undefined>;
const writeTs = (id: string) => call("write", { path: path.join(fakeCwd, "src/a.ts"), content: "export const a = 1;\n" }, id);
const runDeploy = (id: string) => call("bash", { command: "deploy prod" }, id);

// Two pushes arm the escalation for a gated entry (refreshContextCompliance).
for (const id of ["w1", "w2"]) {
	const res = await writeTs(id);
	check(!res?.block, `${id}: a context push must not block`);
	await turnStart();
}

const third = await writeTs("w3");
check(!third?.block, "escalated context push must not block a write");
const delivered = toolResult
	? await toolResult({ toolCallId: "w3", content: [{ type: "text", text: "written" }] }, ctx)
	: undefined;
check(JSON.stringify(delivered ?? "").includes("style-doc"), "write still receives the context reminder on tool_result");

// Cheap actions keep the escalation block.
for (const id of ["b1", "b2"]) {
	const res = await runDeploy(id);
	check(!res?.block, `${id}: first deploy calls push the doc, not block`);
	await turnStart();
}
const blockedBash = await runDeploy("b3");
check(blockedBash?.block === true, "escalated context push must still block a cheap action (bash)");

fs.rmSync(root, { recursive: true, force: true });
if (fail) {
	say(`ESCALATION TESTS: ${fail} failure(s)`);
	process.exit(1);
}
say("ESCALATION TESTS OK");
